select hka_messaging_test.ok(hka_messaging_test.fingerprint()=(select value from hka_messaging_test.fingerprints where label='committed_before_rollback'),'committed rollback preserves every application row including private content and read receipts');
select 'after_rollback',hka_messaging_test.fingerprint();
reset role; select set_config('request.jwt.claim.sub',hka_messaging_test.uid(1)::text,false); set role authenticated;
select hka_messaging_test.ok(exists(select 1 from public.hka_messages where sender_id=hka_messaging_test.uid(9) and recipient_id=hka_messaging_test.uid(1) and student_id is null and body='Adult Horse Owner exact message to Hollie' and read_at is not null) and exists(select 1 from public.hka_messages where sender_id=hka_messaging_test.uid(1) and recipient_id=hka_messaging_test.uid(9) and student_id is null and body='Hollie exact Horse Owner reply' and read_at is null),'Founder retains exact owner history and reply state after committed rollback');
select hka_messaging_test.denied('insert into public.hka_messages(sender_id,recipient_id,student_id,body) values(hka_messaging_test.uid(1),hka_messaging_test.uid(9),null,''Blocked after rollback'')','rollback freezes new Founder direct sends');
select hka_messaging_test.ok(not exists(select 1 from public.hka_message_contacts() where directory_entry),'rollback removes Founder directory');
reset role; select set_config('request.jwt.claim.sub',hka_messaging_test.uid(9)::text,false); set role authenticated;
select hka_messaging_test.ok(exists(select 1 from public.hka_messages where sender_id=hka_messaging_test.uid(9) and recipient_id=hka_messaging_test.uid(1) and student_id is null and body='Adult Horse Owner exact message to Hollie') and exists(select 1 from public.hka_messages where sender_id=hka_messaging_test.uid(1) and recipient_id=hka_messaging_test.uid(9) and student_id is null and body='Hollie exact Horse Owner reply' and read_at is null),'Horse Owner retains both private messages after rollback');
reset role; select set_config('request.jwt.claim.sub',hka_messaging_test.uid(18)::text,false); set role authenticated;
select hka_messaging_test.ok(not exists(select 1 from public.hka_messages where body in ('Adult Horse Owner exact message to Hollie','Hollie exact Horse Owner reply')),'second Admin still cannot read private history after rollback');
select hka_messaging_test.denied('insert into public.hka_messages(sender_id,recipient_id,student_id,body) values(hka_messaging_test.uid(18),hka_messaging_test.uid(9),null,''Unrelated Admin after rollback'')','second Admin cannot send unrelated messages after rollback');
